import { directionOf, type LanguageCode } from '@lexpad/core';
import { cx } from '@/lib/cx.js';
import styles from './Bilingual.module.css';
import { scriptClass } from './script.js';

interface BilingualProps {
  /** The language this text is written in. */
  lang: LanguageCode;
  children: React.ReactNode;
  className?: string | undefined;
  /** Renders a block element instead of an inline span. */
  block?: boolean;
}

/**
 * Text in a specific language, carrying its own direction, face and metrics.
 * Every headword, meaning, gloss, example and translation goes through this,
 * which is what keeps two languages legible in the same row.
 *
 * What the writing system needs is in `script.ts`; what belongs to the
 * language itself -- which way it runs -- is here.
 */
export function Bilingual({ lang, children, className, block = false }: BilingualProps): React.JSX.Element {
  const dir = directionOf(lang);
  const classes = cx(styles.text, scriptClass(lang), className);
  const Tag = block ? 'div' : 'span';
  return (
    <Tag dir={dir} lang={lang} className={classes}>
      {children}
    </Tag>
  );
}

/**
 * Text the user typed, whose language we cannot know. The browser decides
 * the direction from the content itself.
 */
export function UserText({
  children,
  block = false,
}: {
  children: React.ReactNode;
  block?: boolean;
}): React.JSX.Element {
  const Tag = block ? 'div' : 'span';
  return <Tag dir="auto">{children}</Tag>;
}
